1	package util //nolint:revive // util namespace is intentional for shared helpers
2	
3	import (
4		"crypto/rand"
5		"math/big"
6		"net/mail"
7		"strconv"
8		"strings"
9	
10		"github.com/google/uuid"
11	)
12	
13	// ConvertStringToInt32 converts a string to int32.
14	func ConvertStringToInt32(src string) (int32, error) {
15		parsed, err := strconv.ParseInt(src, 10, 32)
16		if err != nil {
17			return 0, err
18		}
19		return int32(parsed), nil
20	}
21	
22	// HasPrefixes returns true if the string s has any of the given prefixes.
23	func HasPrefixes(src string, prefixes ...string) bool {
24		for _, prefix := range prefixes {
25			if strings.HasPrefix(src, prefix) {
26				return true
27			}
28		}
29		return false
30	}
31	
32	// ValidateEmail validates the email.
33	func ValidateEmail(email string) bool {
34		if _, err := mail.ParseAddress(email); err != nil {
35			return false
36		}
37		return true
38	}
39	
40	func GenUUID() string {
41		return uuid.New().String()
42	}
43	
44	var letters = []rune("0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ")
45	
46	// RandomString returns a random string with length n.
47	func RandomString(n int) (string, error) {
48		var sb strings.Builder
49		sb.Grow(n)
50		for i := 0; i < n; i++ {
51			// The reason for using crypto/rand instead of math/rand is that
52			// the former relies on hardware to generate random numbers and
53			// thus has a stronger source of random numbers.
54			randNum, err := rand.Int(rand.Reader, big.NewInt(int64(len(letters))))
55			if err != nil {
56				return "", err
57			}
58			if _, err := sb.WriteRune(letters[randNum.Uint64()]); err != nil {
59				return "", err
60			}
61		}
62		return sb.String(), nil
63	}
64	
65	// ReplaceString replaces all occurrences of old in slice with new.
66	func ReplaceString(slice []string, old, new string) []string {
67		for i, s := range slice {
68			if s == old {
69				slice[i] = new
70			}
71		}
72		return slice
73	}
